CREATE TABLE IF NOT EXISTS milktv_epg_sources (id SERIAL PRIMARY KEY,name TEXT NOT NULL UNIQUE,url TEXT NOT NULL UNIQUE,type TEXT NOT NULL DEFAULT 'xmltv',enabled BOOLEAN NOT NULL DEFAULT FALSE,last_import TIMESTAMP WITHOUT TIME ZONE,import_status TEXT NOT NULL DEFAULT 'never',import_error TEXT,created_at TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT NOW(),updated_at TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS milktv_epg_channels (channel_id INTEGER PRIMARY KEY REFERENCES channels(id) ON DELETE CASCADE,epg_id TEXT,display_name TEXT,match_status TEXT NOT NULL DEFAULT 'unmatched',match_confidence TEXT,updated_at TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS milktv_epg_programmes (id SERIAL PRIMARY KEY,channel_id INTEGER NOT NULL REFERENCES channels(id) ON DELETE CASCADE,start_at TIMESTAMPTZ NOT NULL,stop_at TIMESTAMPTZ NOT NULL,title TEXT NOT NULL,sub_title TEXT,description TEXT,category TEXT,episode TEXT,icon TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(channel_id,start_at,title));
CREATE INDEX IF NOT EXISTS milktv_epg_programmes_channel_start_idx ON milktv_epg_programmes(channel_id,start_at);
CREATE INDEX IF NOT EXISTS milktv_epg_programmes_channel_stop_idx ON milktv_epg_programmes(channel_id,stop_at);
